def repair(g):
    h,w=len(g),len(g[0]); g=[r[:] for r in g]; bad={(i,j) for i in range(h) for j in range(w)}
    def imgs(i,j):
        return [(i,j),(i,w-1-j),(h-1-i,j),(h-1-i,w-1-j),(j,i),(j,w-1-i),(w-1-j,i),(w-1-j,h-1-i)]
    for _ in range(20):
        newbad=set()
        for i in range(h):
            for j in range(w):
                vals={}
                for (a,b) in imgs(i,j):
                    if (a,b) not in bad: vals[g[a][b]]=vals.get(g[a][b],0)+1
                if not vals: newbad.add((i,j)); continue
                v=max(vals,key=vals.get)
                if vals[v]==1 and (i,j) not in bad and len(vals)>1:
                    newbad.add((i,j))
                elif (i,j) in bad or len(vals)>1:
                    g[i][j]=v
                else:
                    g[i][j]=v
        if not newbad: bad=set(); break
        bad=newbad
    return g
def checks(g):
    h,w=len(g),len(g[0])
    return (all(g[i][j]==g[i][w-1-j] for i in range(h) for j in range(w)) and
            all(g[i][j]==g[h-1-i][j] for i in range(h) for j in range(w)) and
            all(g[i][j]==g[h-1-i][w-1-j] for i in range(h) for j in range(w)) and
            all(g[i][j]==g[j][i] for i in range(h) for j in range(w)) and
            all(g[i][j]==g[w-1-j][h-1-i] for i in range(h) for j in range(w)))
r=repair(G['Demo pair 1 input'])
